function buildKma(mode) {
  const pools = mode === 'friend' ? kmaFriendPools : kmaRelationshipPools
  const cards = []
  pools.forEach(([label, items], poolIndex) => {
    deterministicShuffle(combinations(items, 3), 301 + poolIndex * 7).forEach(options => {
      cards.push({ text: `Kiss, marry, avoid. ${label}:`, options })
    })
  })
  return takeTarget(cards, TARGET_PER_MODE, mode === 'friend' ? 307 : 311)
}

