function neverCards(mode) {
  const themes = mode === 'friend' ? friendClaimThemes : relationshipClaimThemes
  const cards = []
  Object.entries(themes).forEach(([theme, claims]) => {
    const suffixKey = theme === 'money' && mode === 'relationship' ? 'relationshipMoney' : theme === 'family' && mode === 'relationship' ? 'relationshipFamily' : theme
    const suffixes = claimSuffixes[suffixKey] || ['']
    claims.forEach(claim => suffixes.forEach(suffix => cards.push({ text: `Never have I ever ${claim}${suffix || '.'}`.replace('..','.') })))
  })
  return takeTarget(cards, TARGET_PER_MODE, mode === 'friend' ? 313 : 317)
}

