function twoTruthCards(mode) {
  const pools = mode === 'friend' ? twoTruthFriendPools : twoTruthRelationshipPools
  const cards = []
  pools.forEach(([label, statements], poolIndex) => {
    deterministicShuffle(combinations(statements, 3), 331 + poolIndex * 5).forEach(group => {
      cards.push({ text: `Two truths and a lie. Pick the three statements you want to use from this ${label} set, then make one the lie.`, statements: group })
    })
  })
  return takeTarget(cards, TARGET_PER_MODE, mode === 'friend' ? 337 : 347)
}

